SELECT



, COUNT(*) OVER() AS total_size
FROM kkdugi_auth_base




AND auth_role_cd LIKE '%' || #{role} || '%'




AND auth_tp_cd = #{type}




AND auth_nm LIKE '%' || #{name} || '%'




ORDER BY auth_role_cd, auth_id
