FROM kkdugi_auth_base
WHERE auth_tp_cd = #{type} AND auth_role_cd = #{role}

mapper.update:
/* QueryID=kkdugi.app.admin.authority.mapper.AdminAuthorityMapper.update */
UPDATE kkdugi_auth_base
SET auth_role_cd = #{role},
    auth_tp_cd   = #{type},
    auth_nm      = #{name},
    auth_dc      = #{remarks},
    use_yn       = #{use},
    upd_dtm      = #{updatedAt},
    upd_id       = #{updaterId}
WHERE auth_id = #{id}

